import hashlib
import hmac
import secrets
import threading


class AccountService:
    def __init__(self) -> None:
        self._accounts = {}
        self._tokens = {}
        self._lock = threading.RLock()

    @staticmethod
    def _password_hash(password: str, salt: bytes) -> bytes:
        # The legacy system treats passwords as case-insensitive.
        return hashlib.pbkdf2_hmac(
            "sha256", password.casefold().encode("utf-8"), salt, 200_000
        )

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters")

        email = email.casefold()
        with self._lock:
            if email in self._accounts:
                raise ValueError("Account already exists")
            salt = secrets.token_bytes(16)
            self._accounts[email] = {
                "salt": salt,
                "password_hash": self._password_hash(password, salt),
                "is_admin": is_admin,
            }

    def login(self, email: str, password: str) -> bool:
        with self._lock:
            account = self._accounts.get(email.casefold())
            if account is None:
                return False
            candidate = self._password_hash(password, account["salt"])
            return hmac.compare_digest(candidate, account["password_hash"])

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        requester_email = requester_email.casefold()
        target_email = target_email.casefold()

        with self._lock:
            requester = self._accounts.get(requester_email)
            if (
                requester is None
                or target_email not in self._accounts
                or (requester_email != target_email and not requester["is_admin"])
            ):
                raise ValueError("Reset request not permitted")

            token = secrets.token_urlsafe(32)
            while token in self._tokens:
                token = secrets.token_urlsafe(32)
            self._tokens[token] = target_email
            return token

    def reset_password(self, token: str, new_password: str) -> None:
        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters")

        with self._lock:
            target_email = self._tokens.get(token)
            if target_email is None:
                raise ValueError("Invalid or used reset token")

            salt = secrets.token_bytes(16)
            password_hash = self._password_hash(new_password, salt)
            account = self._accounts[target_email]
            account["salt"] = salt
            account["password_hash"] = password_hash
            del self._tokens[token]
